const express = require('express');
const app = express();
const _ = require('lodash');

// In-memory session store
const sessions = {};

// Configuration object
const appConfig = {
  dbHost: 'localhost',
  dbPort: 5432,
  dbName: 'myapp',
  adminEmail: 'admin@example.com',
  features: {
    betaMode: false,
    debugLogging: false,
    maintenanceMode: false
  }
};

// Auth middleware
function requireAuth(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || !sessions[token]) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = sessions[token];
  next();
}

// Login endpoint
app.post('/api/login', express.json(), (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check
  if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
    const token = require('crypto').randomBytes(32).toString('hex');
    sessions[token] = { username, role: 'admin', isAdmin: true };
    return res.json({ token, expiresIn: 3600 });
  }
  if (username && password === process.env.USER_PASSWORD) {
    const token = require('crypto').randomBytes(32).toString('hex');
    sessions[token] = { username, role: 'user', isAdmin: false };
    return res.json({ token, expiresIn: 3600 });
  }
  res.status(401).json({ error: 'Invalid credentials' });
});

// User preferences endpoint - deep merge user input into config
app.put('/api/user/preferences', express.json(), requireAuth, (req, res) => {
  const userPrefs = req.body;

  // Validate that user is only updating allowed fields
  const allowedTopLevel = ['theme', 'language', 'notifications', 'display'];
  const filteredPrefs = {};

  for (const key of allowedTopLevel) {
    if (userPrefs[key] !== undefined) {
      filteredPrefs[key] = userPrefs[key];
    }
  }

  // Deep merge filtered preferences into user's stored config
  // Using lodash merge for nested object support
  if (!req.user.preferences) {
    req.user.preferences = {};
  }
  _.merge(req.user.preferences, filteredPrefs);

  res.json({ message: 'Preferences updated', preferences: req.user.preferences });
});

// Admin-only endpoint
app.get('/api/admin/config', requireAuth, (req, res) => {
  if (!req.user.isAdmin) {
    return res.status(403).json({ error: 'Admin access required' });
  }
  res.json(appConfig);
});

// Health check that exposes prototype state (for debugging)
app.get('/api/health', (req, res) => {
  const testObj = {};
  res.json({
    status: 'ok',
    isAdmin: testObj.isAdmin || false,
    polluted: testObj.polluted || false
  });
});

// Config update endpoint (admin only)
app.patch('/api/admin/features', express.json(), requireAuth, (req, res) => {
  if (!req.user.isAdmin) {
    return res.status(403).json({ error: 'Admin access required' });
  }
  _.merge(appConfig.features, req.body);
  res.json({ features: appConfig.features });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
